import * as ecs from "@8thwall/ecs";

import { gameData } from "../core/game-data";
import { GameState } from "../core/game-state";

const CAMERA_DISTANCE = 6;
const CAMERA_HEIGHT = 4;
const LOOK_AHEAD = 1.8;
const CAMERA_SMOOTHING = 5;
const ARENA_LIMIT = 5;

let hasCameraPosition = false;

function clamp(value: number, minimum: number, maximum: number): number {
  return Math.max(minimum, Math.min(maximum, value));
}

ecs.registerComponent({
  name: "camera-follow",

  tick: (world, component) => {
    if (
      gameData.state !== GameState.DRIVING ||
      gameData.truckEid === null ||
      gameData.driveZoneEid === null
    ) {
      return;
    }

    const truck = world.transform.getWorldPosition(gameData.truckEid);
    const zone = world.transform.getWorldPosition(gameData.driveZoneEid);
    const heading = gameData.truckHeading;
    const sinHeading = Math.sin(heading);
    const cosHeading = Math.cos(heading);
    const target = {
      x: truck.x - sinHeading * CAMERA_DISTANCE,
      y: truck.y + CAMERA_HEIGHT,
      z: truck.z - cosHeading * CAMERA_DISTANCE,
    };

    target.x = clamp(target.x, zone.x - ARENA_LIMIT, zone.x + ARENA_LIMIT);
    target.z = clamp(target.z, zone.z - ARENA_LIMIT, zone.z + ARENA_LIMIT);

    const current = world.transform.getWorldPosition(component.eid);
    const blend = hasCameraPosition
      ? Math.min(1, CAMERA_SMOOTHING * Math.min(world.time.delta, 0.05))
      : 1;
    const position = {
      x: current.x + (target.x - current.x) * blend,
      y: current.y + (target.y - current.y) * blend,
      z: current.z + (target.z - current.z) * blend,
    };

    world.transform.setWorldPosition(component.eid, position);
    hasCameraPosition = true;

    const lookAt = {
      x: truck.x + sinHeading * LOOK_AHEAD,
      y: truck.y,
      z: truck.z + cosHeading * LOOK_AHEAD,
    };
    const dx = lookAt.x - position.x;
    const dy = lookAt.y - position.y;
    const dz = lookAt.z - position.z;
    const yaw = Math.atan2(dx, -dz);
    const pitch = Math.atan2(dy, Math.sqrt(dx * dx + dz * dz));
    const halfYaw = yaw / 2;
    const halfPitch = pitch / 2;
    const sinYaw = Math.sin(halfYaw);
    const cosYaw = Math.cos(halfYaw);
    const sinPitch = Math.sin(halfPitch);
    const cosPitch = Math.cos(halfPitch);

    world.transform.setWorldQuaternion(component.eid, {
      x: sinPitch * cosYaw,
      y: cosPitch * sinYaw,
      z: -sinPitch * sinYaw,
      w: cosPitch * cosYaw,
    });
  },
});
